from pathlib import Path
import hashlib,json
p=Path(__file__).resolve().parent
prompt='''Create ONE missing middle animation pose by editing IMAGE 1, the outgoing three-quarter-left James upper-body master. IMAGE 2 is the incoming profile-left master. Keep image 1's exact square canvas framing and registration, but set the head, neck/collar and near shoulder to an orientation HALFWAY between these two references. This must be visibly intermediate: more profile-left than image 1, yet more turned toward the viewer than image 2. Rotate roughly 8 degrees toward profile-left from image 1. Keep the nose/eye/ear and cheek positions anatomically consistent with that middle orientation. Do not simply copy either reference pose. Keep the crown at the same position and head size unchanged; no nod or translation. Articulate neck/collar and near shoulder together; maintain attached backpack, same sleeve patch/symbol and unchanged cropped hands. One mature engineer, same grey-brown hair, forehead goggles and moustache. Preserve image 1 fine painted sprite detail, crop margins, anatomy and proportions. Do not enlarge the face or shoulder patch, move the goggles or redesign insignia.

Use image 1's exact subdued matte palette: neutral charcoal cloth, grey-brown hair, muted ochre engineering patch, natural restrained warm skin and worn grey metal. No purple/magenta tint, orange skin, bright exposure, shiny finish, broad black shadows or pale edge. Genuinely transparent background with original clean antialiased silhouette; preserve real grey hair/silver cuffs. No checkerboard, halo, shadow, text, border or full-body extension. Output one registered upper-body sprite only. The sole pose change is the intermediate small head/neck/shoulder rotation; preserve master identity and material.'''
(p/'middle-prompt.txt').write_text(prompt+'\n',encoding='utf-8')
names=['last-input.png','first-input.png','middle-prompt.txt','late-raw.png']
(p/'middle-inputs.json').write_text(json.dumps({'target':'last-input.png','directionReference':'first-input.png','preCallSha256':{n:hashlib.sha256((p/n).read_bytes()).hexdigest() for n in names},'selected':False},indent=2)+'\n',encoding='utf-8')
print('Middle-angle authoring inputs and prompt frozen.')
